package com.infinitylibrary.builder;
import com.google.gson.*;import java.util.*;import net.minecraft.client.Minecraft;
/** Bounded, ordered model transfer; obsolete chunks never replace a newer draft. */
public final class StudioClient {
 public record Cell(int x,int y,int z,String block){}
 public static final class Model{public String token,id,type,version;public int[] size,offset;public int total,cursor,areaTotal;public long revision;public boolean dirty,undo,redo;public JsonArray areas;public final Map<Long,Cell> blocks=new LinkedHashMap<>();public String note="";}
 public static Model a,b;private static boolean waiting;private static int ticks,waitTicks;public static String status="Open a saved room to start a visual draft.";
 public static long key(int x,int y,int z){return ((long)x<<40)|((long)y<<20)|z;}
 public static int[] vector(JsonObject o,String k){var v=o.getAsJsonArray(k);return new int[]{v.get(0).getAsInt(),v.get(1).getAsInt(),v.get(2).getAsInt()};}
 public static void reset(){a=b=null;waiting=false;status="Open a saved room to start a visual draft.";}
 public static void tick(){ticks++;if(waiting&&++waitTicks>60)waiting=false;if(ticks%4!=0||waiting||!BuilderClient.state.has("token"))return;Model m=a!=null&&(a.cursor<a.total||a.areas.size()<a.areaTotal)?a:b!=null&&(b.cursor<b.total||b.areas.size()<b.areaTotal)?b:null;if(m==null)return;JsonObject o=new JsonObject();o.addProperty("slot",m==a?"a":"b");o.addProperty("model",m.token);o.addProperty("from",m.cursor);o.addProperty("areaFrom",m.areas.size());BuilderClient.send("studio_chunk",o);waiting=true;waitTicks=0;}
 public static void send(String action,JsonObject o){if(a!=null)o.addProperty("draftRevision",a.revision);BuilderClient.send(action,o);}
 public static void send(String action){send(action,new JsonObject());}
 public static void open(String id,boolean discard){JsonObject o=new JsonObject();o.addProperty("room",id);if(discard)o.addProperty("discard",true);BuilderClient.send("studio_open",o);}
 public static void receive(JsonObject o){String kind=o.get("kind").getAsString();boolean primary=o.get("slot").getAsString().equals("a");Model old=primary?a:b;if(kind.equals("studio_model")){String token=o.get("model").getAsString();Model m=old!=null&&old.token.equals(token)?old:new Model();m.token=token;m.id=o.get("room").getAsString();m.type=o.get("type").getAsString();m.version=o.get("version").getAsString();m.size=vector(o,"size");m.offset=vector(o,"offset");m.total=o.get("total").getAsInt();if(m.total<0||m.total>100000)throw new IllegalArgumentException("Model too large");m.revision=o.get("draftRevision").getAsLong();m.dirty=o.get("dirty").getAsBoolean();m.undo=o.get("undo").getAsBoolean();m.redo=o.get("redo").getAsBoolean();if(old==null||!old.token.equals(token)||m.areas==null)m.areas=o.getAsJsonArray("areas");m.areaTotal=o.get("areaTotal").getAsInt();m.note=o.get("pairNote").getAsString();if(primary){a=m;if(!o.get("hasPair").getAsBoolean())b=null;}else b=m;waiting=false;status=primary?"Visual draft ready. Changes affect the draft until Save.":m.note;if(Minecraft.getInstance().gui.screen() instanceof StudioScreen screen){if(primary)screen.modelChanged(old==null||!old.id.equals(m.id));else if(old==null||!old.id.equals(m.id)||!Arrays.equals(old.offset,m.offset)||!Arrays.equals(old.size,m.size))screen.sceneChanged();}}
 else if(kind.equals("studio_blocks")){if(old==null||!old.token.equals(o.get("model").getAsString())||old.cursor!=o.get("from").getAsInt())return;int next=o.get("next").getAsInt();if(next<old.cursor||next>old.total)throw new IllegalArgumentException("Invalid model cursor");for(var item:o.getAsJsonArray("blocks")){var row=item.getAsJsonArray();int x=row.get(0).getAsInt(),y=row.get(1).getAsInt(),z=row.get(2).getAsInt();if(x<0||y<0||z<0||x>=old.size[0]||y>=old.size[1]||z>=old.size[2])throw new IllegalArgumentException("Block outside model");old.blocks.put(key(x,y,z),new Cell(x,y,z,row.get(3).getAsString()));}if(o.has("areas")&&old.areas.size()==o.get("areaFrom").getAsInt())for(var area:o.getAsJsonArray("areas"))old.areas.add(area);old.cursor=next;waiting=false;}
 }
 private StudioClient(){}
}
